// =====================================================================
// EVALUACIÓN DE PLAZOS Y PREPARACIÓN DE EMBED (CATAMARCA UTC-3)
// =====================================================================
const items = $input.all();
const results = [];
const TIMEZONE = 'America/Argentina/Catamarca';
const now = new Date();

// Función para convertir hex a decimal
function hexToDec(hex) {
  if (!hex) return 1096065;
  const clean = hex.replace('#', '').trim();
  const val = parseInt(clean, 16);
  return isNaN(val) ? 1096065 : val;
}

for (const item of items) {
  const row = item.json;
  const eventDate = new Date(row.fecha_inicio);
  const diffMs = eventDate.getTime() - now.getTime();
  const diffHours = diffMs / (1000 * 60 * 60);
  const diffDays = Math.round(diffHours / 24);

  let tipoAviso = null;
  let faltaStr = '';

  if (row.tipo === 'TRIBUNAL_EXAMEN') {
    if (diffDays === 7 && diffHours >= 166 && diffHours <= 170) {
      tipoAviso = '7_DIAS';
      faltaStr = 'en 7 días';
    } else if (diffDays === 1 && diffHours >= 22 && diffHours <= 26) {
      tipoAviso = '1_DIA';
      faltaStr = 'mañana a las 20:00';
    } else if (diffHours >= 1.75 && diffHours <= 2.25) {
      tipoAviso = '2_HORAS';
      faltaStr = 'en 2 horas';
    }
  } else if (row.tipo === 'EVALUACION' || row.tipo === 'TRABAJO_PRACTICO') {
    if (diffDays === 3 && diffHours >= 70 && diffHours <= 74) {
      tipoAviso = '3_DIAS';
      faltaStr = 'en 3 días';
    } else if (diffDays === 1 && diffHours >= 22 && diffHours <= 26) {
      tipoAviso = '1_DIA';
      faltaStr = 'mañana a las 20:00';
    } else if (diffHours >= 10 && diffHours <= 13) {
      tipoAviso = 'DIA_MANANA';
      faltaStr = 'hoy a las 07:30';
    }
  }

  if (tipoAviso) {
    const fields = [
      { name: 'Cátedra', value: row.catedra_nombre || 'General', inline: true },
      { name: 'Fecha', value: eventDate.toLocaleDateString('es-AR', { timeZone: TIMEZONE, weekday: 'long', day: 'numeric', month: 'long' }), inline: true },
      { name: 'Hora', value: eventDate.toLocaleTimeString('es-AR', { timeZone: TIMEZONE, hour: '2-digit', minute: '2-digit' }) + ' hs', inline: true }
    ];
    if (row.aula) fields.push({ name: 'Lugar / Aula', value: row.aula, inline: true });
    if (row.notas) fields.push({ name: 'Detalle', value: row.notas, inline: false });

    results.push({
      json: {
        evento_id: String(row.id),
        tipo_evento: row.tipo,
        tipo_aviso: tipoAviso,
        color: hexToDec(row.color),
        titulo: row.titulo,
        falta: faltaStr,
        fields
      }
    });
  }
}

return results;
